style.css:
@-moz-document domain("moodle.innopolis.university") {
:root {
    --body-bg: #0d120e !important;
    /* Глубокий околочерный с зеленым отливом */
    --page-bg: #161e17 !important;
    /* Мягкий фон подложек */
    --card-bg: #232c24 !important;
    /* Благородный лесной зеленый для блоков и карточек */
    --border-color: #3b4a34 !important;
    /* Сделали цвет границ еще темнее, чтобы убрать белые полосы */
    --text-color: #e8e9e0 !important;
    /* Мягкий молочно-белый текст, приятный глазам */
    --text-muted: #92a079 !important;
    /* Текст описаний и дедлайнов */
    --color_primary: #6d7e5f !important;
    /* Фирменный цвет выделения активных элементов */
}

/* 1. ГЛОБАЛЬНЫЙ СБРОС СВЕТЛЫХ ФОНОВ */
body,
#page,
#page-wrapper,
.wrapper,
#page.drawers .main-inner,
#region-main,
.main-inner,
div[role="main"],
.container-fluid,
[data-region="main-content"],
.bg-white,
.bg-light,
.card,
.block,
.card-body,
.dashboard-card,
.coursebox,
.course-content ul li.section.main,
[data-region="course-content"],
[data-region="recentlyaccessedcourses-view"],
.p-3,
.p-4,
.p-2,
.list-group-item,
section,
.section,
.content,
#frontpage-available-course-list,
#frontpage-course-list,
#frontpage-category-combo,
#frontpage-category-names {
    background-color: var(--body-bg) !important;
    border-color: var(--border-color) !important;
    color: var(--text-color) !important;
}

/* УБИРАЕМ ЯРКИЕ БЕЛЫЕ ЛИНИИ СВЕРХУ И СНИЗУ ПАНЕЛЕЙ */
hr,
.border,
.border-top,
.border-bottom,
#page-header,
.secondary-navigation,
#header,
.navbar {
    border-color: var(--border-color) !important;
}

/* 2. ИСПРАВЛЕНИЕ БЕЛОЙ ПОДЛОЖКИ ПАНЕЛИ ВКЛАДОК */
.secondary-navigation,
div[data-region="secondary-navigation"],
.secondary-navigation .navigation,
.moremenu,
.moremenu .nav-tabs,
.moremenu .nav.nav-tabs,
.nav-tabs,
.nav-item {
    background-color: var(--body-bg) !important;
    border-color: var(--border-color) !important;
}

/* Сами ссылки внутри вкладок по умолчанию (Неактивные) */
.secondary-navigation .nav-link,
.moremenu .nav-link,
.nav-tabs .nav-link {
    background-color: var(--card-bg) !important;
    color: var(--text-muted) !important;
    border: 1px solid var(--border-color) !important;
}

/* Активная вкладка (Например, "Курс") */
.moremenu .nav-link.active,
.nav-tabs .nav-link.active {
    background-color: #2d382e !important;
    color: var(--text-color) !important;
    border-color: var(--border-color) !important;
    border-bottom: 3px solid var(--color_primary) !important;
}

/* Поведение при наведении курсора */
.moremenu .nav-link:not(.active):hover,
.nav-tabs .nav-link:not(.active):hover {
    color: var(--text-color) !important;
    background-color: #1e261f !important;
}

/* 3. КНОПКИ, УПРАВЛЕНИЕ И ФИЛЬТРЫ */
[data-region="filter"],
.bg-white.p-2.mb-4.rounded,
div[data-region="controls"],
div[aria-label="Фильтры курсов"],
.p-2.mb-4.bg-white,
[data-region="controls"] .btn,
.btn,
.btn-secondary,
.dropdown-toggle,
.custom-select,
select,
input {
    background-color: var(--card-bg) !important;
    color: var(--text-color) !important;
    border: 1px solid var(--border-color) !important;
    font-weight: 500 !important;
}

/* Фикс стрелочек слайдера курсов */
.btn-outline-secondary,
button.btn-outline-secondary,
.block_recentlyaccessedcourses button,
[data-region="recentlyaccessedcourses-container"] button {
    background-color: var(--card-bg) !important;
    color: var(--text-color) !important;
    border-color: var(--border-color) !important;
}

.btn-outline-secondary:hover,
button.btn-outline-secondary:hover,
.block_recentlyaccessedcourses button:hover {
    background-color: #2d382e !important;
    color: var(--color_primary) !important;
    border-color: var(--color_primary) !important;
}

/* Чекбоксы завершения тем (Кнопка "Выполнено") */
.btn-outline-success,
.btn-completion,
.btn-completion[data-disabled="true"] {
    border-color: var(--border-color) !important;
    background-color: #2d3b2e !important;
    color: #c4c8ac !important;
}

/* Главная страница и слайдеры */
.frontpage-container,
#site-news-forum,
.subcategories,
.courses,
div[class*="frontpage"],
div[id*="frontpage"],
.coc-category-list,
.course_category_tree {
    background-color: var(--body-bg) !important;
}

.course_category_tree .category > .info,
.coursebox > .info {
    background-color: var(--card-bg) !important;
    border: 1px solid var(--border-color) !important;
}

[data-region="myoverview-courses-view"],
.dashboard-card-deck,
div[data-region="course-view-init"],
div[class^="myoverview"],
.block_myoverview {
    background-color: var(--body-bg) !important;
    border: none !important;
}

/* Шкала времени (Timeline) */
.block_timeline,
[data-region="timeline-view"],
[data-region="event-list"] {
    background-color: var(--body-bg) !important;
}

[data-region="event-list-item"],
.list-group-item.flex-column {
    background-color: var(--card-bg) !important;
    border: 1px solid var(--border-color) !important;
}

/* Календарь */
.calendarwrapper,
.maincalendar,
.maincalendar .calendarmonth,
.maincalendar .calendarmonth td,
.maincalendar .calendarmonth th,
table.calendarmonth th,
table.calendarmonth td {
    background-color: var(--card-bg) !important;
    border: 1px solid var(--border-color) !important;
    box-shadow: none !important;
}

table.calendarmonth td.weekend {
    background-color: #161e17 !important;
}

/* Шрифты, тексты, ссылки */
h1,
h2,
h3,
h4,
h5,
h6,
.page-header-headings h1,
.text-dark,
.coursename,
a.text-dark,
.sectionname a,
.activityname a {
    color: var(--text-color) !important;
}

p,
span,
div,
.text-muted,
.activity-dates,
.contentafterlink,
.automatic-completion-conditions,
.text-black-50,
.text-secondary {
    color: var(--text-muted) !important;
}

.block_calendar_upcoming .card-footer a,
.block .footer a {
    color: #c4c8ac !important;
}

/* Удаление мусора */
img[alt="IU Moodle"],
img[alt="Academi"],
.footer-bootom,
#header .address-head {
    display: none !important;
}

/* ВЫДЕЛЕНИЕ ИКОНОК ФАЙЛОВ И МАТЕРИАЛОВ */
.activityicon,
img.activityicon,
.icon,
.activityiconcontainer img,
img[src*="icon"] {
    filter: invert(1) brightness(5) contrast(2) !important;
    filter: drop-shadow(0px 0px 6px #e8e9e0) !important;
    opacity: 1 !important;
    transition: all 0.2s ease !important;
}

img.activityicon[src*="pdf"],
img.activityicon[src*="document"],
img.activityicon[src*="powerpoint"] {
    filter: brightness(2.5) contrast(1.5) drop-shadow(0px 0px 6px var(--color_primary)) !important;
}

.activity-item:hover .activityicon,
.activity-item:hover img.activityicon {
    filter: invert(1) brightness(8) drop-shadow(0px 0px 10px #ffffff) !important;
    transform: scale(1.1);
}

/* 4. ИСПРАВЛЕНИЕ ЛЕВОЙ ВЫДВИЖНОЙ ПАНЕЛИ (ОГЛАВЛЕНИЕ КУРСА) */
.drawer,
#theme_boost-drawers-courseindex,
[data-region="courseindex-sidebar"],
.courseindex,
.drawercontent {
    background-color: var(--body-bg) !important;
    border-right: 1px solid var(--border-color) !important;
}

.drawerheader,
.drawerheader .drawertoggle {
    background-color: var(--page-bg) !important;
    color: var(--text-color) !important;
    border-bottom: 1px solid var(--border-color) !important;
}

.courseindex-item,
.courseindex-link,
.courseindex-item a {
    color: var(--text-color) !important;
}

.courseindex-item .icon,
.courseindex-item .text-muted,
.courseindex-section-title {
    color: var(--text-muted) !important;
}

.courseindex-item:hover,
.courseindex-item.active {
    background-color: var(--card-bg) !important;
    border-radius: 4px;
}

.courseindex-item:hover a {
    color: var(--color_primary) !important;
}

.drawerheader .btn {
    background-color: transparent !important;
    color: var(--text-color) !important;
    border: none !important;
}

/* 5. ИСПРАВЛЕНИЕ ПРАВОЙ БОКОВОЙ ПАНЕЛИ СООБЩЕНИЙ */
[data-region="message-drawer"],
.message-drawer,
.message-app,
.body-container,
.header-container,
.footer-container,
[data-region="view-overview"],
[data-region="view-conversation"] {
    background-color: var(--card-bg) !important;
    border-left: 1px solid var(--border-color) !important;
    border-color: var(--border-color) !important;
}

.message-app .list-group-item,
[data-region="message-drawer"] .list-group-item,
.nav-all-conversations-container a,
.contact {
    background-color: #1a221b !important;
    border-color: var(--border-color) !important;
}

[data-region="message-drawer"] h3,
[data-region="message-drawer"] h2,
[data-region="message-drawer"] h5,
[data-region="message-drawer"] span,
[data-region="message-drawer"] a,
[data-region="message-drawer"] .font-weight-bold,
.message-drawer .text-dark {
    color: var(--text-color) !important;
}

[data-region="message-drawer"] .text-muted,
[data-region="message-drawer"] p {
    color: var(--text-muted) !important;
}

.message-app input,
[data-region="message-drawer"] input,
[data-region="message-drawer"] .search-input {
    background-color: var(--body-bg) !important;
    color: var(--text-color) !important;
    border: 1px solid var(--border-color) !important;
}

[data-region="message-drawer"] .icon {
    filter: invert(1) brightness(2) !important;
}

/* 6. ИСПРАВЛЕНИЕ МЕНЮ УВЕДОМЛЕНИЙ (КОЛОКОЛЬЧИК) */
.popover-region-container,
.popover-region-menu,
[data-region="notification-popover-container"],
.popover-region-header-container,
.popover-region-footer-container {
    background-color: var(--card-bg) !important;
    border: 1px solid var(--border-color) !important;
}

.popover-region-header-container {
    border-bottom: 1px solid var(--border-color) !important;
}

.popover-region-footer-container {
    border-top: 1px solid var(--border-color) !important;
}

.popover-region-content .notification-image,
.popover-region-content .content-item-container,
.notification-message,
.content-item-container {
    background-color: #1a221b !important;
    border-bottom: 1px solid var(--border-color) !important;
    color: var(--text-color) !important;
    padding: 12px 8px !important;
}

.content-item-container.unread,
.content-item-container:hover {
    background-color: #2d382e !important;
}

.popover-region-header-container h3,
.popover-region-container a,
.popover-region-container span,
.notification-message p,
.notification-meta,
.popover-region-container .time {
    color: var(--text-color) !important;
}

.popover-region-container .time {
    color: var(--text-muted) !important;
    font-size: 0.85em !important;
    display: inline-block !important;
    margin-top: 4px !important;
}

.popover-region-container .view-more,
.popover-region-footer-container .see-all,
.popover-region-footer-container a {
    color: var(--text-color) !important;
    font-weight: bold !important;
}

.popover-region-container .view-more:hover,
.popover-region-footer-container a:hover {
    color: var(--color_primary) !important;
}

.popover-region-header-container .icon,
.popover-region-header-container button {
    filter: invert(1) brightness(2) !important;
    color: var(--text-color) !important;
}

.popover-region-header-container button.close,
.popover-region-header-container .close,
button[aria-label="Close"],
.popover-region-container .close {
    background-color: var(--card-bg) !important;
    color: var(--text-color) !important;
    border: 1px solid var(--border-color) !important;
    opacity: 1 !important;
    border-radius: 4px !important;
    padding: 2px 8px !important;
}

.popover-region-header-container button.close:hover {
    background-color: #2d382e !important;
    color: var(--color_primary) !important;
    border-color: var(--color_primary) !important;
}

/* ПОЛНОЕ УНИЧТОЖЕНИЕ ДЕКОРАТИВНЫХ ПСЕВДОЭЛЕМЕНТОВ И ЛИНИЙ ШАПКИ */
.fixed-top::before,
.fixed-top::after,
#header::before,
#header::after,
.header-main::before,
.header-main::after,
.navbar::before,
.navbar::after,
nav::before,
nav::after,
.page-header::before,
.page-header::after,
#page-header::before,
#page-header::after,
.secondary-navigation::before,
.secondary-navigation::after,
div[data-region="secondary-navigation"]::before,
div[data-region="secondary-navigation"]::after {
    display: none !important;
    content: none !important;
    background: transparent !important;
    height: 0px !important;
}

/* Принудительно красим подложку ВСЕЙ строки навигации, перебивая градиенты */
.fixed-top,
#header,
.header-main,
.navbar,
nav.navbar-bootswatch,
#page-header {
    background-image: none !important;
    background-gradient: none !important;
    background-color: var(--body-bg) !important;
}


/* ИСПРАВЛЕНИЕ ФИОЛЕТОВЫХ ИКОНОК В СООБЩЕНИЯХ */
[data-region="message-drawer"] .icon,
[data-region="message-drawer"] img,
[data-region="message-drawer"] [class*="text-purple"],
[data-region="message-drawer"] .svg {
    filter: brightness(0) invert(1) opacity(0.7) !important;
}

/* 7. ТОТАЛЬНОЕ ИСПРАВЛЕНИЕ ВСЕХ СТРАНИЦ ОЦЕНОК И ПРОФИЛЕЙ */
.path-grade-report-user .main-inner .card,
.path-course-user .main-inner .card,
.path-grade-report-user table,
.path-course-user table,
.path-grade-report-user tr,
.path-course-user tr,
.path-grade-report-user td,
.path-course-user td,
.path-grade-report-user th,
.path-course-user th,
.grades-table,
.grades-table * {
    background-color: var(--card-bg) !important;
    background: var(--card-bg) !important;
    border-color: var(--border-color) !important;
    color: var(--text-color) !important;
}

/* Исправление шапки таблицы (Элемент оценивания, Рассчитанный вес...) */
.path-grade-report-user thead th,
.path-course-user thead th,
.grades-table thead th {
    background-color: #161e17 !important;
    background: #161e17 !important;
    color: var(--text-color) !important;
}

/* Полное удаление проглядывающего белого контура и внешних рамок */
.path-grade-report-user .table-responsive,
.path-course-user .table-responsive,
.path-grade-report-user .user-grade,
.path-course-user .user-grade,
.table-bordered {
    background-color: transparent !important;
    background: transparent !important;
    border: none !important;
    outline: none !important;
    box-shadow: none !important;
}

/* Названия самих заданий и тестов (ссылки) */
.path-grade-report-user td a,
.path-course-user td a,
.grades-table a {
    background-color: transparent !important;
    color: #8cb3d9 !important;
    /* Удобный для чтения голубой цвет */
}

/* Приглушенный текст категорий (Слова "ЗАПОЛНЯЕМЫЙ ВРУЧНУЮ ЭЛЕМЕНТ") */
.path-grade-report-user .text-muted,
.path-course-user .text-muted,
.path-course-user .type {
    color: var(--text-muted) !important;
}

/* ФИКС ДЛЯ УДАЛЕНИЯ БЕЛОЙ ОБЁРТКИ ОЦЕНОК */
.user-report-container,
div[id^="user-report-"],
.path-grade-report-user .user-report-container {
    background-color: var(--body-bg) !important;
    background: var(--body-bg) !important;
    border: none !important;
    box-shadow: none !important;
}


/* 1. ИСПРАВЛЕНИЕ СТРЕЛОЧЕК ПАГИНАЦИИ СЛАЙДЕРА (Фикс для первого скриншота) */
.pagination .page-item .page-link,
.page-link,
ul.pagination.mb-0 .page-link,
ul.pagination.mb-0 .page-item a {
    background-color: var(--card-bg) !important;
    background: var(--card-bg) !important;
    color: var(--text-color) !important;
    border-color: var(--border-color) !important;
}

/* При наведении мышки на стрелочку */
.pagination .page-item .page-link:hover,
.page-link:hover {
    background-color: #2d382e !important;
    color: var(--color_primary) !important;
    border-color: var(--color_primary) !important;
}

/* Состояние, если кнопка заблокирована (нет больше курсов для прокрутки) */
.pagination .page-item.disabled .page-link,
.page-item.disabled .page-link {
    background-color: var(--body-bg) !important;
    color: var(--text-muted) !important;
    border-color: var(--border-color) !important;
    opacity: 0.5 !important;
}

/* 2. ПОЛНОЕ СКРЫТИЕ БЕЛОЙ ПОЛОСЫ #MAINCONTENT (Фикс для второго скриншота) */
#maincontent,
span#maincontent {
    display: none !important;
    height: 0px !important;
    background: transparent !important;
    border: none !important;
    outline: none !important;
}


/* ОКОНЧАТЕЛЬНОЕ УНИЧТОЖЕНИЕ ПОЛОСЫ НАД ОБЗОРОМ КУРСОВ */
.page-mycourses .block_myoverview.block-cards,
div[id^="block-myoverview-"],
.block_myoverview.block-cards,
.block_myoverview {
    border-top: none !important;
    border: none !important;
    box-shadow: none !important;
}


/* УДАЛЕНИЕ НИЖНЕЙ БЕЛОЙ ЛИНИИ У ШАПКИ НАВИГАЦИИ */
.header-main,
div[class*="header-main"],
div[id^="yui_"].header-main,
#header .header-main {
    border-bottom: none !important;
    border-color: transparent !important;
    box-shadow: none !important;
}

/* ИСПРАВЛЕНИЕ СТРЕЛОЧНОЙ НАВИГАЦИИ (ХЛЕБНЫЕ КРОШКИ КУРСОВ) */
.breadcrumb-item,
.breadcrumb,
div[class*="breadcrumb"] a,
div[class*="breadcrumb"] span,
.btn-group .btn:first-child,
/* Если это кастомные кнопки выбора */
[class*="breadcrumb"] * {
    background-color: var(--card-bg) !important;
    background: var(--card-bg) !important;
    color: var(--text-color) !important;
    border-color: var(--border-color) !important;
}

/* Исправление для правой кнопки со стрелкой («Найти») */
.btn-group .btn:last-child,
button[type="submit"],
.search-input button {
    background-color: var(--color_primary) !important;
    background: var(--color_primary) !important;
    color: #ffffff !important;
    /* Делаем текст «Найти» чисто белым и контрастным */
    border-color: var(--color_primary) !important;
}

/* Если стрелка сделана через CSS-бордеры (треугольники) */
.breadcrumb-item::after,
[class*="breadcrumb"]::after {
    border-left-color: var(--card-bg) !important;
    color: var(--text-muted) !important;
}

/* ИСПРАВЛЕНИЕ БЕЛОЙ ШАПКИ ТАБЛИЦЫ УЧАСТНИКОВ */
.path-user .table thead th,
.path-user thead,
.path-user th,
#participants th {
    background-color: var(--card-bg) !important;
    background: var(--card-bg) !important;
    color: var(--text-color) !important;
    border-color: var(--border-color) !important;
}

/* ОЧИСТКА ЛОГОТИПА ИННОПОЛИСА ДО ИДЕАЛЬНО БЕЛОГО ЦВЕТА */
.navbar-brand img,
.navbar-brand .logo img,
img[alt*="Innopolis"],
.header-main .logo img {
    filter: grayscale(1) invert(1) brightness(1.8) contrast(1.5) !important;
    opacity: 0.9 !important;
}


/* ПРИГЛУШЕНИЕ ГРАНИЦ БЛОКОВ КУРСА */
.course-section .section-item,
.section-item,
.course-section,
#section-0 .section-item,
li[id^="section-"] .section-item {
    border-color: var(--border-color) !important;
}

/* ПРИГЛУШЕНИЕ РАЗДЕЛИТЕЛЬНЫХ ЛИНИЙ МЕЖДУ МАТЕРИАЛАМИ */
.course-content .section li.activity,
.activity,
li[id^="module-"] {
    border-top: 1px solid var(--border-color) !important;
}

/* ПРИГЛУШЕНИЕ ЛИНИЙ НАД ОПИСАНИЯМИ И ДЕДЛАЙНАМИ */
.activity-item .activity-altcontent.activity-description,
.activity-altcontent,
.activity-description {
    border-top: 1px solid var(--border-color) !important;
}


/* ИСПРАВЛЕНИЕ БЕЛОЙ ШАПКИ НА СТРАНИЦЕ ОБЗОРА ОЦЕНОК */
.path-grade-report-overview table thead th,
.path-grade-report-overview .generaltable thead th,
.path-grade-report-overview th,
#overview-grade th {
    background-color: var(--card-bg) !important;
    background: var(--card-bg) !important;
    color: var(--text-color) !important;
    border-bottom: 2px solid var(--border-color) !important;
}

/* Мягко приглушаем нижние горизонтальные линии строк в этой таблице */
.path-grade-report-overview .generaltable td,
.path-grade-report-overview .generaltable tr {
    border-color: var(--border-color) !important;
}

    /* ОКОНЧАТЕЛЬНОЕ ИСПРАВЛЕНИЕ ТАБЛИЦЫ ОЦЕНОК ПО СЕЛЕКТОРАМ ИЗ DEVTOOLS */
    .path-grade-report-user .user-grade,
    .path-grade-report-user .generaltable,
    .grade-report-user .user-grade th.category,
    .grade-report-user .user-grade td,
    .path-grade-report-user table,
    .path-grade-report-user tr,
    .path-grade-report-user td,
    .path-grade-report-user th,
    .path-grade-report-user tbody,
    .path-grade-report-user thead {
        background-color: var(--card-bg) !important;
        background: var(--card-bg) !important;
        border-color: var(--border-color) !important;
        color: var(--text-color) !important;
    }

    /* Перекрашиваем шапку таблицы (Элемент оценивания, Рассчитанный вес...) */
    .path-grade-report-user thead th,
    .path-grade-report-user thead tr,
    .grade-report-user .user-grade thead th {
        background-color: #161e17 !important;
        background: #161e17 !important;
        color: var(--text-color) !important;
    }

    /* Делаем ссылки на задания (Exam Grade, Task 1...) яркими и читаемыми */
    .path-grade-report-user td a,
    .path-grade-report-user td a span,
    .user-grade td a {
        background-color: transparent !important;
        background: transparent !important;
        color: #8cb3d9 !important; /* Наш нежно-голубой цвет для ссылок */
    }

    /* Приглушаем серый служебный текст ("ЗАПОЛНЯЕМЫЙ ВРУЧНУЮ ЭЛЕМЕНТ") */
    .path-grade-report-user .text-muted,
    .path-grade-report-user .type,
    .grade-report-user .type {
        color: var(--text-muted) !important;
    }

    /* Убираем белый фон у внешнего контейнера-обертки таблицы */
    .grade-report-user,
    .table-responsive,
    div[class*="grade-report-user"] {
        background-color: transparent !important;
        background: transparent !important;
        border: none !important;
    }


    /* ИСПРАВЛЕНИЕ БЕЛОГО ПЕРВОГО СТОЛБЦА В ТАБЛИЦЕ ОЦЕНОК */
    .path-grade-report-user .user-grade th[id^="row_"],
    .path-grade-report-user .user-grade th,
    .user-grade tbody th,
    .user-grade .itemname,
    table.generaltable tbody th {
        background-color: var(--card-bg) !important;
        background: var(--card-bg) !important;
        color: var(--text-color) !important;
        border-color: var(--border-color) !important;
    }


    /* ИСПРАВЛЕНИЕ ВЫПАДАЮЩЕГО МЕНЮ ПЕРЕКЛЮЧЕНИЯ ОТЧЕТОВ */
    .dropdown-menu,
    .dropdown-menu.show,
    div[id^="dropdown-menu-"],
    .dropdown-item {
        background-color: var(--card-bg) !important;
        background: var(--card-bg) !important;
        color: var(--text-color) !important;
        border: 1px solid var(--border-color) !important;
    }

    /* Сами строчки внутри выпадающего списка (Просмотр, Обзорный отчет...) */
    .dropdown-item,
    .dropdown-menu a,
    .dropdown-menu span {
        color: var(--text-color) !important;
        background: transparent !important;
    }

    /* Подсветка элемента при наведении мышки */
    .dropdown-item:hover,
    .dropdown-menu a:hover {
        background-color: #2d382e !important;
        color: var(--text-color) !important;
    }

    /* Активный выбранный пункт (отмеченный зеленой галочкой) */
    .dropdown-item.active,
    .dropdown-item[aria-current="true"] {
        background-color: #1e261f !important;
        color: var(--text-color) !important;
    }


    /* ИСПРАВЛЕНИЕ РЕДАКТОРА TINYMCE И ЕГО ПАНЕЛИ ИНСТРУМЕНТОВ */
    .tox-tinymce,
    .tox .tox-menubar,
    .tox .tox-toolbar,
    .tox .tox-toolbar__primary,
    .tox .tox-toolbar__overflow,
    .tox .tox-statusbar,
    div[class*="tox-"] {
        background-color: var(--card-bg) !important;
        background: var(--card-bg) !important;
        border-color: var(--border-color) !important;
        color: var(--text-color) !important;
    }

    /* Выпадающие списки и кнопки меню редактора */
    .tox .tox-mbtn,
    .tox .tox-tbtn,
    .tox .tox-tbtn--disabled,
    .tox .tox-mbtn--select {
        background-color: transparent !important;
        color: var(--text-color) !important;
    }

    /* Эффект наведения мыши на иконки и кнопки редактора */
    .tox .tox-tbtn:hover,
    .tox .tox-mbtn:hover,
    .tox .tox-mbtn--active {
        background-color: #2d382e !important;
        color: var(--text-color) !important;
    }

    /* Сами иконки на кнопках (сброс черного цвета) */
    .tox .tox-tbtn svg,
    .tox .tox-mbtn svg,
    .tox svg {
        fill: var(--text-color) !important;
        color: var(--text-color) !important;
    }

    /* Нижняя строка состояния ("слов - 0 Build with TinyMCE") */
    .tox .tox-statusbar a,
    .tox .tox-statusbar__path-item,
    .tox .tox-statusbar__wordcount {
        color: var(--text-muted) !important;
    }


    /* ИСПРАВЛЕНИЕ ОКОН ЗАГРУЗКИ ФАЙЛОВ (FILE PICKER) */
    .fp-dialog,
    .fp-dialog .modal-content,
    .filepicker-filemanager,
    .moodle-dialogue-base .moodle-dialogue-wrap,
    .moodle-dialogue-base .moodle-dialogue-hd,
    .modal-dialog,
    .modal-content {
        background-color: var(--card-bg) !important;
        background: var(--card-bg) !important;
        border: 1px solid var(--border-color) !important;
        color: var(--text-color) !important;
    }

    /* Шапка модального окна (Название файла, кнопка закрытия) */
    .modal-header,
    .moodle-dialogue-hd {
        background-color: #1a221b !important;
        border-bottom: 1px solid var(--border-color) !important;
        color: var(--text-color) !important;
    }

    /* Подвал окна управления файлами (Нижняя белая часть с кнопками "Обновление", "Отмена") */
    .modal-footer,
    .fp-content-center,
    .fp-options {
        background-color: var(--card-bg) !important;
        background: var(--card-bg) !important;
        border-top: 1px solid var(--border-color) !important;
    }

    /* Текст подписей (Название, Автор, Выберите лицензию, Путь...) */
    .fp-dialog label,
    .fp-dialog span,
    .fp-dialog div,
    .modal-body,
    .modal-body label,
    .modal-body span {
        color: var(--text-color) !important;
    }

    /* Текст технических деталей внизу (Размер, Разрешение, Дата изменения) */
    .fp-dialog .form-meta,
    .fp-dialog .form-meta * {
        color: var(--text-muted) !important;
    }

    /* Кнопка-крестик закрытия окна справа сверху */
    .modal-header .close,
    .moodle-dialogue-hd .close,
    button.close {
        color: var(--text-color) !important;
        text-shadow: none !important;
        opacity: 0.8 !important;
    }
    .modal-header .close:hover {
        color: var(--color_primary) !important;
        opacity: 1 !important;
    }
}
